const TZ = 'Europe/Lisbon';
const hoje = DateTime.now().setZone(TZ).startOf('day');
const hojeStr = hoje.toFormat('yyyy-MM-dd');
function parseData(v) {
  if (!v) return null;
  const s = String(v).trim();
  let d = DateTime.fromISO(s, { zone: TZ });
  if (!d.isValid) d = DateTime.fromFormat(s, 'dd/MM/yyyy', { zone: TZ });
  return d.isValid ? d.startOf('day') : null;
}
function diasDesde(v) {
  const d = parseData(v);
  return d ? Math.floor(hoje.diff(d, 'days').days) : Infinity;
}

const P = $input.all().map(i => i.json);
const semana = v => diasDesde(v) <= 6;
const pct = (a, b) => (b ? Math.round((a / b) * 100) : 0);

const convites = P.filter(p => semana(p.data_convite)).length;
const aceites = P.filter(p => semana(p.data_ligacao)).length;
const respostas = P.filter(p => semana(p.data_resposta)).length;
const leads = P.filter(p => p.estado === 'lead' && semana(p.data_resposta));
const contactados = P.filter(p => (Number(p.passo) || 0) >= 1).length;
const responderam = P.filter(p => p.data_resposta).length;
const leadsTotal = P.filter(p => p.estado === 'lead').length;

const taxaAceite = pct(aceites, convites);
const taxaResposta = pct(responderam, contactados);
const taxaLead = pct(leadsTotal, responderam);
const novos = P.filter(p => p.estado === 'novo').length;
const pendentes = P.filter(p => p.estado === 'convite_enviado').length;
const emSequencia = P.filter(p => ['ligado', 'em_sequencia'].includes(p.estado)).length;

const diag = [];
if (convites < 100) diag.push(`Só ${convites} convites esta semana (meta 100): verifica erros na coluna "notas" ou a lista de novos.`);
if (convites >= 20 && taxaAceite < 30) diag.push('Aceitação abaixo de 30%: melhora o perfil (título/banner) ou aperta o ICP.');
if (contactados >= 20 && taxaResposta < 25) diag.push('Resposta abaixo de 25%: personaliza mais a abertura (passo 0).');
if (responderam >= 10 && taxaLead < 40) diag.push('Resposta→lead abaixo de 40%: qualifica melhor a dor ou testa outra oferta.');
if (novos < 100) diag.push(`Só restam ${novos} prospects novos: adiciona mais ao Sales Navigator/Sheet (meta 400+).`);
if (pendentes > 100) diag.push(`${pendentes} convites pendentes: acima de 100 aumenta o risco de restrição.`);
if (!diag.length) diag.push('Tudo dentro das metas. Mantém a rotina.');

const cor = (v, meta) => `<b style="color:${v >= meta ? '#1a7f37' : '#cf222e'}">${v}</b>`;
const html = `
<h2>LinkedIn — semana até ${hoje.toFormat('dd/MM/yyyy')}</h2>
<table cellpadding="6" style="border-collapse:collapse">
<tr><td>Leads esta semana</td><td>${cor(leads.length, 10)} / 10</td></tr>
<tr><td>Convites enviados</td><td>${cor(convites, 100)} / 100</td></tr>
<tr><td>Novas ligações</td><td>${aceites}</td></tr>
<tr><td>Taxa de aceitação</td><td>${cor(taxaAceite, 35)}% (meta &gt;35%)</td></tr>
<tr><td>Respostas esta semana</td><td>${respostas}</td></tr>
<tr><td>Taxa de resposta (acumulada)</td><td>${cor(taxaResposta, 25)}% (meta &gt;25%)</td></tr>
<tr><td>Resposta → lead (acumulada)</td><td>${cor(taxaLead, 40)}% (meta &gt;40%)</td></tr>
<tr><td>Em sequência</td><td>${emSequencia}</td></tr>
<tr><td>Convites pendentes</td><td>${pendentes}</td></tr>
<tr><td>Prospects novos na lista</td><td>${novos}</td></tr>
</table>
<h3>Diagnóstico</h3><ul>${diag.map(d => `<li>${d}</li>`).join('')}</ul>
<h3>Leads da semana</h3><ul>${leads.map(l => `<li><a href="${l.linkedin_url}">${l.nome}</a> — ${l.cargo || ''} ${l.empresa ? '@ ' + l.empresa : ''}: ${l.resumo_ia || ''}</li>`).join('') || '<li>Nenhuma</li>'}</ul>`;

return [{ json: { assunto: `📊 LinkedIn: ${leads.length} leads esta semana`, html } }];

const TZ = 'Europe/Lisbon';
const hoje = DateTime.now().setZone(TZ).startOf('day');
const hojeStr = hoje.toFormat('yyyy-MM-dd');
function parseData(v) {
  if (!v) return null;
  const s = String(v).trim();
  let d = DateTime.fromISO(s, { zone: TZ });
  if (!d.isValid) d = DateTime.fromFormat(s, 'dd/MM/yyyy', { zone: TZ });
  return d.isValid ? d.startOf('day') : null;
}
function diasDesde(v) {
  const d = parseData(v);
  return d ? Math.floor(hoje.diff(d, 'days').days) : Infinity;
}

const dias = Number($('Config').first().json.dias_ate_retirar_convite) || 21;
return $input.all()
  .map(i => i.json)
  .filter(p => p.estado === 'convite_enviado' && p.invitation_id && p.provider_id && diasDesde(p.data_convite) >= dias)
  .map(p => ({ json: { provider_id: p.provider_id, invitation_id: p.invitation_id } }));
